<?php
namespace App\Http\Middleware;
use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class SecurityHeaders{public function handle(Request $request,Closure $next):Response{$response=$next($request);$headers=['X-Content-Type-Options'=>'nosniff','X-Frame-Options'=>'DENY','Referrer-Policy'=>'strict-origin-when-cross-origin','Permissions-Policy'=>'camera=(self), microphone=(self), geolocation=()','Cross-Origin-Opener-Policy'=>'same-origin','Cross-Origin-Resource-Policy'=>'same-origin','Content-Security-Policy'=>"default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data: https:; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'",];foreach($headers as $key=>$value)$response->headers->set($key,$value);if($request->isSecure())$response->headers->set('Strict-Transport-Security','max-age=31536000; includeSubDomains');return$response;}}
